-- Testimonials Manager — demo seed. Generated by database/build-seed.php; safe to re-run (idempotent).

SET NAMES utf8mb4;

SET FOREIGN_KEY_CHECKS = 0;

  ON DUPLICATE KEY UPDATE password_hash = VALUES(password_hash), display_name = VALUES(display_name);

  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), image = VALUES(image);

  ON DUPLICATE KEY UPDATE product_id = VALUES(product_id), url = VALUES(url), title = VALUES(title), description = VALUES(description), image = VALUES(image), status = VALUES(status), removed_at = NULL;

  ON DUPLICATE KEY UPDATE author_name = VALUES(author_name), text = VALUES(text), rating = VALUES(rating), gender = VALUES(gender), url = VALUES(url), is_active = VALUES(is_active), sort_order = VALUES(sort_order);

  ON DUPLICATE KEY UPDATE sort_order = VALUES(sort_order);

SET FOREIGN_KEY_CHECKS = 1;
