INSERT INTO users (id, username, password_hash, display_name) VALUES (1, 'admin', '$2y$10$lKeoI67xkC7CLArMDsBOX.a.CaSCXGvCDWvx/39z5j6cDhshhxBoO', 'Demo Admin')
INSERT INTO products (id, parent_sku, title, description, image) VALUES
  (1, 'abforge', 'Strengthen your abs with smart rebound power!', 'Introducing AbForge™, the must-have addition to your home gym. Engineered for effective ab training, it delivers targeted core workouts with automatic rebound assistance and adjustable resistance levels. Build strength, sculpt your stomach, and boost endurance – all from the comfort of your home!', 'https://s-mania.com/v1/en/abforge/product-img/var-1.webp'),
  (2, 'casavella', 'Fresh Pasta. Hand-Crafted Perfection!', 'Durable manual pasta machine with an aluminum body, adjustable table clamp, and eco-friendly crank for easy homemade cavatelli and macaroni.', 'https://s-mania.com/v1/en/casavella/product-img/var-1.webp'),
  (3, 'drivewaypro', 'Renew your driveway in a snap', 'Does your driveway look worn? DrivewayPRO™ is the ultimate solution for restoring and protecting asphalt and concrete surfaces. With its resistance to inclement weather, temperature changes, cracking and UV damage, DrivewayPRO™ not only improves the appearance of your driveway, but also provides long-lasting waterproofing and protection.', 'https://s-mania.com/v1/en/drivewaypro/product-img/var-1.webp'),
  (4, 'playfort', 'Create a wonderful playground for your children\'s joy and development!', 'Durable & stable playground for kids up to 3 years old!', 'https://s-mania.com/v1/en/playfort/product-img/var-1.webp'),
  (5, 'poolclean', 'Achieve Crystal Clear Pools Instantly!', 'Transform your pool maintenance routine today with PoolClean. Forget the hassle; just a sprinkle of our magic powder, and watch as it effortlessly dissolves, leaving you with a pristine pool. Dive into pure relaxation without the wait!', 'https://s-mania.com/v1/en/poolclean/product-img/var-1.webp'),
  (6, 'royalride', 'ROYAL RIDE, ELECTRIC ADVENTURE!', 'A powerful 12V dual-drive electric motorcycle for kids, featuring Prince (blue) and Princess (pink) editions for a stable and thrilling ride-on experience.', 'https://s-mania.com/v1/en/royalride/product-img/var-1.webp'),
  (7, 'spaetzlepro', 'Perfect homemade pasta made easy!', 'A high-quality stainless steel spätzle slicer with a heat-resistant handle and universal fit, designed for fast, professional-grade pasta making and easy cleaning.', 'https://s-mania.com/v1/en/spaetzlepro/product-img/var-1.webp'),
  (8, 'spikeback', 'Perfect your passes!', 'Transform your football or volleyball skills at home with the revolutionary SpikeBack™ rebounder net! Experience unparalleled control, precision, and agility as this dynamic rebounder returns the ball with perfect accuracy every time.', 'https://s-mania.com/v1/en/spikeback/product-img/var-1.webp'),
  (9, 'veloraluxe', 'Drill-free toilet paper holder with a glamorous touch!', 'Your ultimate solution for a sleek and efficient bathroom experience!', 'https://s-mania.com/v1/en/veloraluxe/product-img/var-1.webp'),
  (10, 'woodydraw', 'Smart storage that brings calm to your countertop.', 'Bring effortless organization and natural elegance to your home with this stylish countertop organizer. Crafted from sturdy materials, it offers both beauty and durability while keeping your essentials neatly in place. The spacious drawer adds convenient access and extra room for your everyday items, making your space cleaner, calmer, and perfectly put together.', 'https://s-mania.com/v1/en/woodydraw/product-img/var-1.webp')
INSERT INTO landings (id, product_id, country, is_master, url, title, description, image, status, last_synced_at) VALUES
  (61763, 1, 'EN', 1, 'https://s-mania.com/v1/en/abforge', 'Strengthen your abs with smart rebound power!', 'Introducing AbForge™, the must-have addition to your home gym. Engineered for effective ab training, it delivers targeted core workouts with automatic rebound assistance and adjustable resistance levels. Build strength, sculpt your stomach, and boost endurance – all from the comfort of your home!', 'https://s-mania.com/v1/en/abforge/product-img/var-1.webp', 'READY FOR ADVERTISEMENT', '2026-09-13 12:00:00'),
  (63138, 1, 'BG', 0, 'https://s-mania.com/v1/bg/abforge', 'Укрепете коремните си мускули с умна възстановителна сила!', 'Представяме ви AbForge™, задължителното допълнение към вашата домашна фитнес зала. Проектиран за ефективно трениране на коремните мускули, той предлага целенасочени тренировки за ядрото с автоматична помощ при възстановяване и регулируеми нива на съпротивление. Изградете сила, оформете корема си и увеличете издръжливостта – всичко това от уюта на вашия дом!', 'https://s-mania.com/v1/bg/abforge/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (63133, 1, 'CZ', 0, 'https://s-mania.com/v1/cz/abforge', 'Posilte své břišní svaly chytrou rebound silou!', 'Představujeme AbForge™, nezbytný doplněk vaší domácí posilovny. Navržen pro efektivní trénink břišních svalů, poskytuje cílené cvičení na střed těla s automatickou pomocí při odrazu a nastavitelnými úrovněmi odporu. Budujte sílu, tvarujte svůj žaludek a zvyšte vytrvalost – to vše z pohodlí vašeho domova!', 'https://s-mania.com/v1/cz/abforge/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (63139, 1, 'DE', 0, 'https://s-mania.de/v1/k/abforge', 'Stärken Sie Ihre Bauchmuskeln mit intelligenter Rückstoßkraft!', 'Präsentation von AbForge™, der unverzichtbaren Ergänzung für dein Home Gym. Entwickelt für effektives Bauchtraining, bietet es gezielte Core-Workouts mit automatischer Rückfederungshilfe und einstellbaren Widerstandsstufen. Stärke aufbauen, deinen Bauch formen und die Ausdauer steigern – alles bequem von zu Hause aus!', 'https://s-mania.de/v1/k/abforge/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (65762, 1, 'EE', 0, 'https://s-mania.com/v1/ee/abforge', 'Tugevda oma kõhulihaseid nutika tagasilöögi jõuga!', 'Tutvustame AbForge™-i, hädavajaliku täienduse sinu kodusesse jõusaali. Loodud tõhusaks kõhulihaste treeninguks, pakub see sihipäraseid keretreeninguid automaatse tagasikerimise abiga ja reguleeritavate takistustasemetega. Arenda jõudu, vormi oma', 'https://s-mania.com/v1/ee/abforge/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (63135, 1, 'GR', 0, 'https://s-mania.com/v1/gr/abforge', 'Ενδυναμώστε τους κοιλιακούς σας με έξυπνη δύναμη επαναφοράς!', 'Παρουσιάζουμε το AbForge™, την απαραίτητη προσθήκη στο γυμναστήριο του σπιτιού σας. Σχεδιασμένο για αποτελεσματική εκπαίδευση κοιλιακών, προσφέρει στοχευμένες προπονήσεις πυρήνα με αυτόματη βοήθεια επαναφοράς και ρυθμιζόμενα επίπεδα αντίστασης. Δημιουργήστε δύναμη, σμιλέψτε την κοιλιά σας και ενισχύστε την αντοχή σας – όλα από την άνεση του σπιτιού σας!', 'https://s-mania.com/v1/gr/abforge/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61766, 1, 'HR', 0, 'https://s-mania.com/v1/hr/abforge', 'OJAČAJ SVOJE TRBUŠNJAKE UZ PAMETNU SNAGU POVRATNOG MEHANIZMA!', 'Predstavljamo AbForge™, neizostavan dodatak vašoj kućnoj teretani. Dizajniran za učinkovit trening trbušnih mišića, pruža ciljane vježbe za core s automatskom pomoći pri oporavku i podesivim razinama otpora. Izgradite snagu, oblikujte trbuh i povećajte izdržljivost – sve iz udobnosti svog doma!', 'https://s-mania.com/v1/hr/abforge/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61764, 1, 'HU', 0, 'https://s-mania.com/v1/hu/abforge', 'Erősítsd a hasizmaidat intelligens visszapattanó erővel!', 'Bemutatjuk az AbForge™-t, az otthoni edzőterem elengedhetetlen kiegészítőjét. A hatékony hasizom-edzéshez tervezett készülék célzott törzsedzéseket biztosít automatikus visszapattanási segítséggel és állítható ellenállási szintekkel. Építsen erőt, formálja a hasát és fokozza az állóképességet - mindezt otthonról, kényelmesen!', 'https://s-mania.com/v1/hu/abforge/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (63137, 1, 'IT', 0, 'https://s-mania.it/v1/abforge', 'Rafforza i tuoi addominali con il potere del rimbalzo intelligente!', 'Presentiamo AbForge™, l\'aggiunta indispensabile al tuo home gym. Progettato per un allenamento addominale efficace, offre allenamenti mirati per il core con assistenza al rimbalzo automatica e livelli di resistenza regolabili. Costruisci forza, scolpisci il tuo addome e aumenta la resistenza – tutto dal comfort di casa tua!', 'https://s-mania.it/v1/abforge/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (63140, 1, 'LT', 0, 'https://s-mania.com/v1/lt/abforge', 'Sustiprinkite savo pilvo raumenis su protinga atšokimo galia!', 'Pristatome AbForge™, būtinas priedas jūsų namų sporto salėje. Sukurtas efektyviam pilvo raumenų treniravimui, jis suteikia tikslinius core treniruotes su automatinėmis atšokimo pagalbos funkcijomis ir reguliuojamais pasipriešinimo lygiais. Stiprinkite jėgą, formuokite pilvą ir didinkite ištvermę – viską patogiai savo namuose!', 'https://s-mania.com/v1/lt/abforge/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (65763, 1, 'LV', 0, 'https://s-mania.com/v1/lv/abforge', 'Stiprini savu vēderpresi ar viedu atsitiena jaudu!', 'Iepazīstinām ar AbForge™, obligātu papildinājumu jūsu mājas sporta zālei. Izstrādāts efektīviem vēdera muskuļu treniņiem, tas nodrošina mērķtiecīgus ķermeņa kodola treniņus ar automātisku atsitiena palīdzību un regulējamiem pretestības līmeņiem. Veidojiet spēku, veidojiet vēdera presi un uzlabojiet izturību – viss no jūsu mājas ērtībām!', 'https://s-mania.com/v1/lv/abforge/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (63136, 1, 'PL', 0, 'https://s-mania.com/v1/pl/abforge', 'Wzmocnij swoje mięśnie brzucha dzięki inteligentnej mocy odbicia!', 'Przedstawiamy AbForge™, niezbędny element Twojej domowej siłowni. Zaprojektowany z myślą o skutecznym treningu mięśni brzucha, oferuje ukierunkowane ćwiczenia na rdzeń z automatyczną pomocą w odbiciu i regulowanymi poziomami oporu. Buduj siłę, rzeźb swoje brzuch i zwiększaj wytrzymałość – wszystko to w komfortowych warunkach swojego domu!', 'https://s-mania.com/v1/pl/abforge/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61765, 1, 'RO', 0, 'https://s-mania.com/v1/ro/abforge', 'Întărește-ți abdomenul cu putere de revenire inteligentă!', 'Vă prezentăm AbForge™, o completare indispensabilă a sălii dvs. de sport de acasă. Proiectat pentru un antrenament eficient al abdomenului, acesta oferă antrenamente de bază direcționate cu asistență automată la revenire și niveluri de rezistență reglabile. Dezvoltă-ți forța, sculptează-ți abdomenul și stimulează rezistența - toate din confortul casei tale!', 'https://s-mania.com/v1/ro/abforge/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61777, 1, 'RS', 0, 'https://s-mania.com/v1/rs/abforge', 'Ojačajte svoje trbušne mišiće pametnom snagom skokova!', 'Predstavljamo AbForge™, neophodni dodatak vašoj kućnoj teretani. Dizajniran za efikasan trening trbušnih mišića, pruža ciljane vežbe za jezgro sa automatskom pomoći pri oporavku i podesivim nivoima otpora. Izgradite snagu, oblikujte stomak i povećajte izdržljivost – sve iz udobnosti svog doma!', 'https://s-mania.com/v1/rs/abforge/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (63132, 1, 'SI', 0, 'https://smania.si/v1/abforge', 'Okrepite trebušne mišice s pametno povratno močjo!', 'Predstavljamo AbForge™ – nepogrešljiv dodatek za vašo domačo telovadnico. Zasnovan je za učinkovito vadbo trebušnih mišic ter omogoča ciljno usmerjeno krepitev jedra telesa s samodejno povratno pomočjo in nastavljivimi stopnjami upora. Zgradite moč, oblikujte trebuh in izboljšajte vzdržljivost – vse iz udobja svojega doma!', 'https://smania.si/v1/abforge/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (63134, 1, 'SK', 0, 'https://s-mania.com/v1/sk/abforge', 'Posilnite svoje brucho s inteligentnou odrazovou silou!', 'Predstavujeme AbForge™, nevyhnutný doplnok do vašej domácej posilňovne. Navrhnutý pre efektívny tréning brucha, poskytuje cielené tréningy jadra s automatickou pomocou pri odraze a nastaviteľnými úrovňami odporu. Budujte silu, formujte svoj žalúdok a zvyšujte vytrvalosť – všetko z pohodlia vášho domova!', 'https://s-mania.com/v1/sk/abforge/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (63914, 2, 'EN', 1, 'https://s-mania.com/v1/en/casavella', 'Fresh Pasta. Hand-Crafted Perfection!', 'Durable manual pasta machine with an aluminum body, adjustable table clamp, and eco-friendly crank for easy homemade cavatelli and macaroni.', 'https://s-mania.com/v1/en/casavella/product-img/var-1.webp', 'READY FOR ADVERTISEMENT', '2026-09-13 12:00:00'),
  (65471, 2, 'BG', 0, 'https://s-mania.com/v1/bg/casavella', 'Прясна паста. Ръчно изработено съвършенство!', 'Устойчива ръчна машина за паста с алуминиево тяло, регулируем статив и екологична ръкохватка за лесно приготвяне на домашни кавателли и макарони.', 'https://s-mania.com/v1/bg/casavella/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (65466, 2, 'CZ', 0, 'https://s-mania.com/v1/cz/casavella', 'Čerstvé těstoviny. Ručně vyrobená dokonalost!', 'Odolný manuální stroj na těstoviny s hliníkovým tělem, nastavitelným stolem a ekologickou klikou pro snadnou výrobu domácích cavatelli a makarónů.', 'https://s-mania.com/v1/cz/casavella/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (65473, 2, 'DE', 0, 'https://s-mania.de/v1/k/casavella', 'Frische Pasta. Handwerkliche Perfektion!', 'Robuste manuelle Nudelmaschine mit einem Aluminiumgehäuse, verstellbarem Tischklemmen und umweltfreundlichem Handkurbel für die einfache Zubereitung von hausgemachten Cavatelli und Makkaroni.', 'https://s-mania.de/v1/k/casavella/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66057, 2, 'EE', 0, 'https://s-mania.com/v1/ee/casavella', 'Värske pasta. Käsitööna loodud täiuslikkus!', 'Vastupidav käsitsi pastamasin alumiiniumkorpuse, reguleeritava lauaklambi ja keskkonnasõbraliku vändaga hõlpsaks koduseks cavatelli ja makaroni valmistamiseks.', 'https://s-mania.com/v1/ee/casavella/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (65468, 2, 'GR', 0, 'https://s-mania.com/v1/gr/casavella', 'Φρέσκια Ζυμαρικά. Χειροποίητη Τελειότητα!', 'Ανθεκτική χειροποίητη μηχανή ζυμαρικών με αλουμινένιο σώμα, ρυθμιζόμενο σφιγκτήρα τραπεζιού και οικολογική μανιβέλα για εύκολη παρασκευή σπιτικών καβατελλί και μακαρονιών.', 'https://s-mania.com/v1/gr/casavella/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (63915, 2, 'HR', 0, 'https://s-mania.com/v1/hr/casavella', 'Svježa tjestenina. Ručno izrađena savršenstvo!', 'Izdržljiva ručna mašina za tjesteninu s aluminijskim tijelom, podesivom stezaljkom za stol i ekološkim ručnim mehanizmom za jednostavno pripremanje domaćih cavatelli i macaroni.', 'https://s-mania.com/v1/hr/casavella/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (63916, 2, 'HU', 0, 'https://s-mania.com/v1/hu/casavella', 'Friss tészta. Kézműves tökéletesség!', 'Tartós, kézi tészta gép alumínium házzal, állítható asztali szorítóval és környezetbarát kézi hajtókarra, amely megkönnyíti a házi Cavatelli és Macaroni készítését.', 'https://s-mania.com/v1/hu/casavella/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (65470, 2, 'IT', 0, 'https://s-mania.it/v1/casavella', 'Pasta Fresca. Perfezione Artigianale!', 'Macchina per pasta manuale durevole con corpo in alluminio, morsetto da tavolo regolabile e manovella ecologica per preparare facilmente cavatelli e macaroni fatti in casa.', 'https://s-mania.it/v1/casavella/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (65474, 2, 'LT', 0, 'https://s-mania.com/v1/lt/casavella', 'Šviežia makaronai. Rankų darbo tobulumas!', 'Patvari rankinė makaronų mašina su aliuminio korpusu, reguliuojamu stalo laikikliu ir ekologiniu rankenėle, skirta lengvai pagaminti naminius cavatelli ir makaronus.', 'https://s-mania.com/v1/lt/casavella/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66058, 2, 'LV', 0, 'https://s-mania.com/v1/lv/casavella', 'Svaiga pasta. Ar rokām darināta pilnība!', 'Izturīga manuāla makaronu mašīna ar alumīnija korpusu, regulējamu galda stiprinājumu un videi draudzīgu kloķi ērtai mājās gatavotu kavatelli un makaronu pagatavošanai.', 'https://s-mania.com/v1/lv/casavella/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (65469, 2, 'PL', 0, 'https://s-mania.com/v1/pl/casavella', 'Świeże makarony. Ręcznie robione mistrzostwo!', 'Trwała ręczna maszyna do makaronu z aluminiowym korpusem, regulowanym uchwytem stołowym i ekologiczną korbką, idealna do łatwego przygotowywania domowych cavatelli i makaronu.', 'https://s-mania.com/v1/pl/casavella/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (63917, 2, 'RO', 0, 'https://s-mania.com/v1/ro/casavella', 'Paste proaspete. Perfecțiune lucrată manual!', 'Mașină de paste manuală durabilă, cu carcasă din aluminiu, clemă de masă ajustabilă și manivelă ecologică pentru a prepara cu ușurință Cavatelli și Macaroni făcute în casă.', 'https://s-mania.com/v1/ro/casavella/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64268, 2, 'RS', 0, 'https://s-mania.com/v1/rs/casavella', 'Sveža testenina. Ručno rađena savršenost!', 'Izdržljiva ručna mašina za testeninu sa aluminijumskim kućištem, podesivim stolnim držačem i ekološkom ručkom za jednostavno pravljenje domaćih kavatelija i makarona.', 'https://s-mania.com/v1/rs/casavella/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (65465, 2, 'SI', 0, 'https://smania.si/v1/casavella', 'Sveže testenine. Ročno izdelana popolnost!', 'Trpežen ročni aparat za testenine z aluminijastim ohišjem, nastavljivo namizno spono in okolju prijaznim ročajem za enostavno pripravo domačih testenin cavatelli in makaronov.', 'https://smania.si/v1/casavella/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (65467, 2, 'SK', 0, 'https://s-mania.com/v1/sk/casavella', 'Čerstvé cestoviny. Ručne vyrobené dokonalosti!', 'Trvanlivá ručná stroj na cestoviny s hliníkovým telom, nastaviteľnou svorkou na stôl a ekologickou kľukou pre jednoduché domáce cavatelli a makaróny.', 'https://s-mania.com/v1/sk/casavella/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (59654, 3, 'EN', 1, 'https://s-mania.com/v1/en/drivewaypro', 'Renew your driveway in a snap', 'Does your driveway look worn? DrivewayPRO™ is the ultimate solution for restoring and protecting asphalt and concrete surfaces. With its resistance to inclement weather, temperature changes, cracking and UV damage, DrivewayPRO™ not only improves the appearance of your driveway, but also provides long-lasting waterproofing and protection.', 'https://s-mania.com/v1/en/drivewaypro/product-img/var-1.webp', 'READY FOR ADVERTISEMENT', '2026-09-13 12:00:00'),
  (61386, 3, 'AT', 0, 'https://s-mania.at/v1/drivewaypro', 'Erneuern Sie Ihre Einfahrt im Handumdrehen', 'Sieht Ihre Auffahrt abgenutzt aus? DrivewayPRO™ ist die ultimative Lösung für die Restaurierung und den Schutz von Asphalt- und Betonflächen. DrivewayPRO™ ist witterungsbeständig, resistent gegen Temperaturschwankungen, Risse und UV-Schäden und verbessert nicht nur das Aussehen Ihrer Einfahrt, sondern bietet auch lang anhaltende Wasserdichtigkeit und Schutz.', 'https://s-mania.at/v1/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61380, 3, 'BG', 0, 'https://s-mania.com/v1/bg/drivewaypro', 'Обновяване на алеята за един миг', 'Изглежда ли алеята ви износена? DrivewayPRO™ е най-доброто решение за възстановяване и защита на асфалтови и бетонни повърхности. Със своята устойчивост на неблагоприятни атмосферни условия, температурни промени, напукване и увреждане от ултравиолетовите лъчи DrivewayPRO™ не само подобрява външния вид на вашата алея, но и осигурява дълготрайна хидроизолация и защита.', 'https://s-mania.com/v1/bg/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61373, 3, 'CZ', 0, 'https://s-mania.com/v1/cz/drivewaypro', 'Obnova příjezdové cesty během chvilky', 'Vypadá vaše příjezdová cesta opotřebovaně? DrivewayPRO™ je dokonalé řešení pro obnovu a ochranu asfaltových a betonových povrchů. Díky své odolnosti vůči nepřízni počasí, změnám teplot, praskání a poškození UV zářením DrivewayPRO™ nejen zlepšuje vzhled vaší příjezdové cesty, ale také poskytuje dlouhotrvající hydroizolaci a ochranu.', 'https://s-mania.com/v1/cz/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61381, 3, 'DE', 0, 'https://s-mania.de/v1/k/drivewaypro', 'Erneuern Sie Ihre Einfahrt im Handumdrehen', 'Sieht Ihre Auffahrt abgenutzt aus? DrivewayPRO™ ist die ultimative Lösung für die Restaurierung und den Schutz von Asphalt- und Betonflächen. DrivewayPRO™ ist witterungsbeständig, resistent gegen Temperaturschwankungen, Risse und UV-Schäden und verbessert nicht nur das Aussehen Ihrer Einfahrt, sondern bietet auch lang anhaltende Wasserdichtigkeit und Schutz.', 'https://s-mania.de/v1/k/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61385, 3, 'EE', 0, 'https://s-mania.com/v1/ee/drivewaypro', 'Uuendage oma sõiduteed hetkega', 'Kas teie sõidutee näeb kulunud välja? DrivewayPRO™ on parim lahendus asfalt- ja betoonpindade taastamiseks ja kaitsmiseks. DrivewayPRO™ on vastupidav ebasoodsatele ilmastikutingimustele, temperatuurimuutustele, pragudele ja UV-kahjustustele ning see mitte ainult ei paranda teie sõidutee välimust, vaid tagab ka pikaajalise veekindluse ja kaitse.', 'https://s-mania.com/v1/ee/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (65089, 3, 'ES', 0, 'https://s-mania.com/v1/es/drivewaypro', 'Renueva tu entrada en un abrir y cerrar de ojos.', '¿Tu entrada de coches se ve desgastada? DrivewayPRO™ es la solución definitiva para restaurar y proteger superficies de asfalto y hormigón. Con su resistencia a las inclemencias del tiempo, cambios de temperatura, agrietamiento y daños por UV, DrivewayPRO™ no solo mejora la apariencia de tu entrada, sino que también ofrece un sellado y protección impermeables de larga duración.', 'https://s-mania.com/v1/es/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61376, 3, 'GR', 0, 'https://s-mania.com/v1/gr/drivewaypro', 'Ανανεώστε το δρόμο σας σε χρόνο μηδέν', 'Φαίνεται φθαρμένος ο δρόμος σας Το DrivewayPRO™ είναι η απόλυτη λύση για την αποκατάσταση και την προστασία των επιφανειών ασφάλτου και σκυροδέματος. Με την αντοχή του στις κακές καιρικές συνθήκες, τις αλλαγές θερμοκρασίας, τις ρωγμές και τις βλάβες από την υπεριώδη ακτινοβολία, το DrivewayPRO™ όχι μόνο βελτιώνει την εμφάνιση του δρόμου σας, αλλά παρέχει επίσης μακροχρόνια στεγανοποίηση και προστασία.', 'https://s-mania.com/v1/gr/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (59656, 3, 'HR', 0, 'https://s-mania.com/v1/hr/drivewaypro', 'Obnovite svoj prilaz u tren oka', 'Izgleda li vaš prilaz istrošeno? DrivewayPRO™ je ultimativno rješenje za obnovu i zaštitu asfaltnih i betonskih površina. Sa svojom otpornošću na loše vremenske uvjete, temperaturne promjene, pucanje i UV oštećenja, DrivewayPRO™ ne samo da poboljšava izgled vašeg prilaza, već također pruža dugotrajnu vodonepropusnost i zaštitu.', 'https://s-mania.com/v1/hr/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61375, 3, 'HU', 0, 'https://s-mania.com/v1/hu/drivewaypro', 'Egy pillanat alatt megújítja a felhajtót', 'Kopottnak tűnik a felhajtója? A DrivewayPRO™ a végső megoldás az aszfalt- és betonfelületek helyreállítására és védelmére. A kedvezőtlen időjárással, hőmérséklet-változásokkal, repedésekkel és UV-károsodással szembeni ellenálló képességével a DrivewayPRO™ nem csak a felhajtóút megjelenését javítja, hanem hosszú távú vízszigetelést és védelmet is biztosít.', 'https://s-mania.com/v1/hu/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61379, 3, 'IT', 0, 'https://s-mania.it/v1/drivewaypro', 'Rinnovate il vostro vialetto in un attimo', 'Il vostro vialetto sembra usurato? DrivewayPRO™ è la soluzione definitiva per ripristinare e proteggere le superfici in asfalto e cemento. Grazie alla sua resistenza alle intemperie, agli sbalzi di temperatura, alle crepe e ai danni causati dai raggi UV, DrivewayPRO™ non solo migliora l\'aspetto del vostro vialetto, ma fornisce anche un\'impermeabilizzazione e una protezione durature.', 'https://s-mania.it/v1/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61384, 3, 'LT', 0, 'https://s-mania.com/v1/lt/drivewaypro', 'Akimirksniu atnaujinkite važiuojamąją dalį', 'Ar jūsų važiuojamoji dalis atrodo nusidėvėjusi? "DrivewayPRO™" yra geriausias sprendimas asfalto ir betono paviršiams atkurti ir apsaugoti. Dėl atsparumo nepalankioms oro sąlygoms, temperatūrų pokyčiams, įtrūkimams ir UV spinduliams DrivewayPRO™ ne tik pagerina jūsų važiuojamosios dalies išvaizdą, bet ir užtikrina ilgalaikę hidroizoliaciją ir apsaugą.', 'https://s-mania.com/v1/lt/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61383, 3, 'LV', 0, 'https://s-mania.com/v1/lv/drivewaypro', 'Atjaunojiet savu piebraucamo ceļu vienā mirklī', 'Vai jūsu piebraucamais ceļš izskatās nolietojies? DrivewayPRO™ ir vislabākais risinājums asfalta un betona virsmu atjaunošanai un aizsardzībai. Ar savu noturību pret nelabvēlīgiem laikapstākļiem, temperatūras izmaiņām, plaisāšanu un UV starojuma bojājumiem DrivewayPRO™ ne tikai uzlabo Jūsu brauktuves izskatu, bet arī nodrošina ilglaicīgu hidroizolāciju un aizsardzību.', 'https://s-mania.com/v1/lv/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61382, 3, 'NL', 0, 'https://s-mania.nl/v1/drivewaypro', 'Vernieuw je oprit in een handomdraai', 'Ziet je oprit er versleten uit? DrivewayPRO™ is de ultieme oplossing voor het herstellen en beschermen van asfalt en betonnen oppervlakken. Met zijn weerstand tegen guur weer, temperatuurschommelingen, scheuren en UV-schade verbetert DrivewayPRO™ niet alleen het uiterlijk van uw oprit, maar biedt het ook langdurige waterdichting en bescherming.', 'https://s-mania.nl/v1/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61378, 3, 'PL', 0, 'https://s-mania.com/v1/pl/drivewaypro', 'Odnów swój podjazd w mgnieniu oka', 'Czy Twój podjazd wygląda na zużyty? DrivewayPRO™ to najlepsze rozwiązanie do renowacji i ochrony powierzchni asfaltowych i betonowych. Dzięki odporności na niekorzystne warunki pogodowe, zmiany temperatury, pękanie i uszkodzenia spowodowane promieniowaniem UV, DrivewayPRO™ nie tylko poprawia wygląd podjazdu, ale także zapewnia długotrwałą wodoodporność i ochronę.', 'https://s-mania.com/v1/pl/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (65090, 3, 'PT', 0, 'https://s-mania.com/v1/pt/drivewaypro', 'Renove seu caminho rapidamente', 'Seu caminho de entrada parece desgastado? O DrivewayPRO™ é a solução definitiva para restaurar e proteger superfícies de asfalto e concreto. Com sua resistência a condições climáticas adversas, variações de temperatura, fissuras e danos causados pelos raios UV, o DrivewayPRO™ não apenas melhora a aparência do seu caminho de entrada, mas também oferece impermeabilização e proteção duradouras.', 'https://s-mania.com/v1/pt/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (59657, 3, 'RO', 0, 'https://s-mania.com/v1/ro/drivewaypro', 'Reînnoiți carosabilul într-o clipă', 'Aleea dvs. pare uzată? DrivewayPRO™ este soluția supremă pentru refacerea și protejarea suprafețelor din asfalt și beton. Datorită rezistenței sale la intemperii, la schimbările de temperatură, la crăpături și la deteriorarea cauzată de razele UV, DrivewayPRO™ nu numai că îmbunătățește aspectul aleii dvs.', 'https://s-mania.com/v1/ro/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61377, 3, 'RS', 0, 'https://s-mania.com/v1/rs/drivewaypro', 'Obnovite svoj prilaz u trenutku', 'Da li vam prilaz izgleda istrošeno? DrivewayPRO™ je vrhunsko rešenje za obnavljanje i zaštitu asfaltnih i betonskih površina. Zahvaljujući svojoj otpornosti na nepovoljne vremenske uslove, promene temperature, pucanje i UV oštećenja, DrivewayPRO™ ne samo da poboljšava izgled vašeg prilaza, već pruža i dugotrajnu hidroizolaciju i zaštitu.', 'https://s-mania.com/v1/rs/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61372, 3, 'SI', 0, 'https://smania.si/v1/drivewaypro', 'Obnovite svojo dovozno pot v trenutku', 'Ali je vaša dovozna pot videti obrabljena? DrivewayPRO™ je najboljša rešitev za obnovo in zaščito asfaltnih in betonskih površin. S svojo odpornostjo na slabe vremenske razmere, temperaturne spremembe, razpoke in poškodbe zaradi UV-žarkov DrivewayPRO™ ne izboljša le videza vaše dovozne poti, temveč zagotavlja tudi dolgotrajno hidroizolacijo in zaščito.', 'https://smania.si/v1/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61374, 3, 'SK', 0, 'https://s-mania.com/v1/sk/drivewaypro', 'Obnovte svoju príjazdovú cestu v okamihu', 'Vyzerá vaša príjazdová cesta opotrebovane? DrivewayPRO™ je dokonalé riešenie na obnovu a ochranu asfaltových a betónových povrchov. Vďaka svojej odolnosti voči nepriaznivému počasiu, teplotným zmenám, praskaniu a poškodeniu UV žiarením DrivewayPRO™ nielen zlepšuje vzhľad vašej príjazdovej cesty, ale poskytuje aj dlhotrvajúcu hydroizoláciu a ochranu.', 'https://s-mania.com/v1/sk/drivewaypro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
