  (60907, 4, 'LT', 0, 'https://s-mania.com/v1/lt/playfort', 'Sukurkite nuostabią žaidimų aikštelę vaikų džiaugsmui ir tobulėjimui!', 'Patvari ir stabili žaidimų aikštelė vaikams iki 3 metų!', 'https://s-mania.com/v1/lt/playfort/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (60906, 4, 'LV', 0, 'https://s-mania.com/v1/lv/playfort', 'Izveidojiet brīnišķīgu rotaļu laukumu savu bērnu priekam un attīstībai!', 'Izturīgs un stabils rotaļu laukums bērniem līdz 3 gadu vecumam!', 'https://s-mania.com/v1/lv/playfort/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (60905, 4, 'NL', 0, 'https://s-mania.nl/v1/playfort', 'Creëer een prachtige speelplaats voor het plezier en de ontwikkeling van je kinderen!', 'Duurzame & stabiele speeltuin voor kinderen tot 3 jaar!', 'https://s-mania.nl/v1/playfort/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (60900, 4, 'PL', 0, 'https://s-mania.com/v1/pl/playfort', 'Stwórz wspaniały plac zabaw dla radości i rozwoju swoich dzieci!', 'Trwały i stabilny plac zabaw dla dzieci w wieku do 3 lat!', 'https://s-mania.com/v1/pl/playfort/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (59800, 4, 'RO', 0, 'https://s-mania.com/v1/ro/playfort', 'Creați un loc de joacă minunat pentru bucuria și dezvoltarea copilului dumneavoastră!', 'Loc de joacă durabil și stabil pentru copii până la 3 ani!', 'https://s-mania.com/v1/ro/playfort/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (60899, 4, 'RS', 0, 'https://s-mania.com/v1/rs/playfort', 'Napravite divno igralište za radost i razvoj vaše dece!', 'Izdržljivo i stabilno igralište za decu do 3 godine!', 'https://s-mania.com/v1/rs/playfort/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (60895, 4, 'SI', 0, 'https://smania.si/v1/playfort', 'Ustvarite čudovito igrišče za veselje in razvoj svojih otrok!', 'Vzdržljivo in stabilno igrišče za otroke do 3. leta starosti!', 'https://smania.si/v1/playfort/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (60897, 4, 'SK', 0, 'https://s-mania.com/v1/sk/playfort', 'Vytvorte nádherné ihrisko pre radosť a rozvoj vašich detí!', 'Odolné a stabilné ihrisko pre deti do 3 rokov!', 'https://s-mania.com/v1/sk/playfort/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61758, 5, 'EN', 1, 'https://s-mania.com/v1/en/poolclean', 'Achieve Crystal Clear Pools Instantly!', 'Transform your pool maintenance routine today with PoolClean. Forget the hassle; just a sprinkle of our magic powder, and watch as it effortlessly dissolves, leaving you with a pristine pool. Dive into pure relaxation without the wait!', 'https://s-mania.com/v1/en/poolclean/product-img/var-1.webp', 'READY FOR ADVERTISEMENT', '2026-09-13 12:00:00'),
  (64909, 5, 'BG', 0, 'https://s-mania.com/v1/bg/poolclean', 'Постигнете кристално ясни басейни мигновено!', 'Преобразете своята рутинна грижа за басейна днес с PoolClean. Забравете за неудобствата; просто поръсете малко от нашия магически прах и наблюдавайте как той лесно се разтваря, оставяйки ви с кристално чист басейн. Потопете се в истинско спокойствие без чакане!', 'https://s-mania.com/v1/bg/poolclean/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64902, 5, 'CZ', 0, 'https://s-mania.com/v1/cz/poolclean', 'Dosáhněte okamžitě křišťálově čistých bazénů!', 'Transformujte svou rutinu údržby bazénu dnes s PoolClean. Zapomeňte na potíže; stačí trochu našeho magického prášku a sledujte, jak se bez námahy rozpouští a zanechává váš bazén v dokonalém stavu. Ponořte se do čistého odpočinku bez čekání!', 'https://s-mania.com/v1/cz/poolclean/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64910, 5, 'DE', 0, 'https://s-mania.de/v1/k/poolclean', 'Erzielen Sie sofort kristallklare Pools!', 'Verändern Sie noch heute Ihre Poolpflege-Routine mit PoolClean. Vergessen Sie den Aufwand; ein wenig von unserem Zauberpulver reicht aus, und sehen Sie zu, wie es sich mühelos auflöst und Ihnen einen makellosen Pool hinterlässt. Tauchen Sie ein in reine Entspannung ohne Wartezeit!', 'https://s-mania.de/v1/k/poolclean/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64913, 5, 'EE', 0, 'https://s-mania.com/v1/ee/poolclean', 'Saavutage kohe kristallselged basseinid!', 'Muuda oma basseinihooldus rutiin täna PoolCleaniga. Unusta vaev; lihtsalt väike ports meie imepulbrit ja vaata, kuidas see vaevata lahustub, jättes sulle puhta basseini. Sukeldu puhasesse lõõgastushetke ilma ootamiseta!', 'https://s-mania.com/v1/ee/poolclean/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (65081, 5, 'ES', 0, 'https://s-mania.com/v1/es/poolclean', '¡Consigue Piscinas Cristalinas al Instante!', 'Transforma tu rutina de mantenimiento de piscina hoy con PoolClean. Olvídate de las complicaciones; solo un poco de nuestro polvo mágico, y observa cómo se disuelve sin esfuerzo, dejándote con una piscina impecable. ¡Sumérgete en la pura relajación sin esperar!', 'https://s-mania.com/v1/es/poolclean/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64905, 5, 'GR', 0, 'https://s-mania.com/v1/gr/poolclean', 'Αποκτήστε Κρυστάλλινα Καθαρά Πισίνες Άμεσα!', 'Μεταμορφώστε τη ρουτίνα συντήρησης της πισίνας σας σήμερα με το PoolClean. Ξεχάστε τον κόπο; Μόνο μια ρίξιμο από τη μαγική μας σκόνη και παρακολουθήστε την να διαλύεται εύκολα, αφήνοντάς σας με μια κρυστάλλινη πισίνα. Βυθιστείτε στην απόλυτη χαλάρωση χωρίς αναμονές!', 'https://s-mania.com/v1/gr/poolclean/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61775, 5, 'HR', 0, 'https://s-mania.com/v1/hr/poolclean', 'Trenutačno postignite kristalno čiste bazene!', 'Transformirajte svoju rutinu održavanja bazena već danas uz PoolClean. Zaboravite na gnjavažu; samo pospite naš čarobni prah i gledajte kako se bez napora otapa, ostavljajući vam besprijekoran bazen. Uronite u čisto opuštanje bez čekanja!', 'https://s-mania.com/v1/hr/poolclean/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61773, 5, 'HU', 0, 'https://s-mania.com/v1/hu/poolclean', 'Azonnal kristálytiszta medencék elérése!', 'Alakítsa át medencéje karbantartási rutinját még ma a PoolClean segítségével. Felejtse el a gondot; csak egy szórás a varázsporunkból, és nézze meg, ahogy könnyedén feloldódik, és egy makulátlan medencét hagy maga után. Merüljön el a tiszta kikapcsolódásban várakozás nélkül!', 'https://s-mania.com/v1/hu/poolclean/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64908, 5, 'IT', 0, 'https://s-mania.it/v1/poolclean', 'Ottieni piscine cristalline immediatamente!', 'Trasforma la tua routine di manutenzione della piscina oggi stesso con PoolClean. Dimentica il fastidio; basta una spruzzata della nostra polvere magica e guarda come si dissolve senza sforzo, lasciandoti con una piscina impeccabile. Tuffati in un puro relax senza attese!', 'https://s-mania.it/v1/poolclean/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64912, 5, 'LT', 0, 'https://s-mania.com/v1/lt/poolclean', 'Pasiekite krištolo skaidrumo baseinus akimirksniu!', 'Transformuokite savo baseino priežiūros rutiną šiandien su PoolClean. Pamirškite nepatogumus; tiesiog užbarstykite šiek tiek mūsų stebuklingų miltelių, ir stebėkite, kaip jie lengvai ištirps, palikdami jums švarų baseiną. Paskendkite į gryną poilsį be laukimo!', 'https://s-mania.com/v1/lt/poolclean/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64911, 5, 'LV', 0, 'https://s-mania.com/v1/lv/poolclean', 'Iegūstiet kristāldzidrus peldbaseinus nekavējoties!', 'Pārveidojiet savu baseina kopšanas rutīnu šodien ar PoolClean. Aizmirstiet par grūtībām; vienkārši uzberiet mūsu burvīgo pulveri, un skatieties, kā tas viegli izšķīst, atstājot jums nevainojamu baseinu. Iegremdējieties tīrā relaksācijā bez gaidīšanas!', 'https://s-mania.com/v1/lv/poolclean/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64907, 5, 'PL', 0, 'https://s-mania.com/v1/pl/poolclean', 'Osiągnij Kryształowo Czyste Baseny Natychmiast!', 'Zmień swoją rutynę konserwacji basenu już dziś z PoolClean. Zapomnij o kłopotach; wystarczy odrobina naszego magicznego proszku, a zobaczysz, jak łatwo się rozpuszcza, pozostawiając cię z nieskazitelnym basenem. Zanurz się w czystym relaksie bez czekania!', 'https://s-mania.com/v1/pl/poolclean/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (65082, 5, 'PT', 0, 'https://s-mania.com/v1/pt/poolclean', 'Alcance Piscinas Cristalinas Instantaneamente!', 'Transforme sua rotina de manutenção da piscina hoje com o PoolClean. Esqueça o trabalho duro; basta uma pitada do nosso pó mágico e veja como ele se dissolve sem esforço, deixando sua piscina impecável. Mergulhe na pura relaxamento sem esperar!', 'https://s-mania.com/v1/pt/poolclean/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (61774, 5, 'RO', 0, 'https://s-mania.com/v1/ro/poolclean', 'Obțineți instantaneu piscine cristaline!', 'Transformați-vă astăzi rutina de întreținere a piscinei cu PoolClean. Uitați de complicații; doar un strop din pudra noastră magică și priviți cum se dizolvă fără efort, lăsându-vă cu o piscină imaculată. Scufundați-vă în relaxare pură, fără așteptare!', 'https://s-mania.com/v1/ro/poolclean/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64906, 5, 'RS', 0, 'https://s-mania.com/v1/rs/poolclean', 'Postignite kristalno čiste bazene odmah!', 'Transformišite svoju rutinu održavanja bazena danas uz PoolClean. Zaboravite na komplikacije; samo malo našeg magičnog praha, i posmatrajte kako se bez napora rastvara, ostavljajući vam besprekornu vodu. Uživajte u potpunom opuštanju bez čekanja!', 'https://s-mania.com/v1/rs/poolclean/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64901, 5, 'SI', 0, 'https://smania.si/v1/poolclean', 'DO KRISTALNO ČISTEGA BAZENA V TRENUTKU!', 'Poenostavite vzdrževanje svojega bazena s PoolClean. Brez zapletenega čiščenja – samo posujte naš čistilni prašek in opazujte, kako se hitro raztopi ter za seboj pusti čist in osvežen bazen. Uživajte v popolni sprostitvi brez čakanja!', 'https://smania.si/v1/poolclean/product-img/var-1.webp', 'NOT ADVERTISING', '2026-09-13 12:00:00'),
  (64903, 5, 'SK', 0, 'https://s-mania.com/v1/sk/poolclean', 'Dosiahnite krištáľovo čisté bazény okamžite!', 'Transformujte svoju rutinu starostlivosti o bazén dnes s PoolClean. Zabudnite na komplikácie; stačí posypať naším magickým práškom a sledujte, ako sa bez námahy rozpúšťa, pričom vám zanecháva čistý bazén. Ponorte sa do čistej relaxácie bez čakania!', 'https://s-mania.com/v1/sk/poolclean/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64709, 6, 'EN', 1, 'https://s-mania.com/v1/en/royalride', 'ROYAL RIDE, ELECTRIC ADVENTURE!', 'A powerful 12V dual-drive electric motorcycle for kids, featuring Prince (blue) and Princess (pink) editions for a stable and thrilling ride-on experience.', 'https://s-mania.com/v1/en/royalride/product-img/var-1.webp', 'READY FOR ADVERTISEMENT', '2026-09-13 12:00:00'),
  (66762, 6, 'BG', 0, 'https://s-mania.com/v1/bg/royalride', 'КРАЛСКО ПЪТУВАНЕ, ЕЛЕКТРИЧЕСКО ПРИКЛЮЧЕНИЕ!', 'Мощен 12V електрически мотоциклет с двойно задвижване за деца, предлагащ издания „Принц“ (син) и „Принцеса“ (розов) за стабилно и вълнуващо изживяване при каране.', 'https://s-mania.com/v1/bg/royalride/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66757, 6, 'CZ', 0, 'https://s-mania.com/v1/cz/royalride', 'KRÁLOVSKÁ JÍZDA, ELEKTRICKÉ DOBRODRUŽSTVÍ!', 'Silná 12V elektrická motorka s pohonem obou kol pro děti, dostupná ve verzích Princ (modrá) a Princezna (růžová) pro stabilní a vzrušující zážitek z jízdy.', 'https://s-mania.com/v1/cz/royalride/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66763, 6, 'DE', 0, 'https://s-mania.de/v1/k/royalride', 'KÖNIGLICHE FAHRT, ELEKTRISCHES ABENTEUER!', 'Ein leistungsstarkes 12V Doppelantriebs-Elektromotorrad für Kinder, erhältlich in den Prinz- (blau) und Prinzessin- (rosa) Editionen, für ein stabiles und aufregendes Fahrerlebnis.', 'https://s-mania.de/v1/k/royalride/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66766, 6, 'EE', 0, 'https://s-mania.com/v1/ee/royalride', 'KUNINGLIK SÕIT, ELEKTRILINE SEIKLUS!', 'Võimas 12V kaheveoline elektriline mootorratas lastele, millel on Printsi (sinine) ja Printsess (roosa) versioonid, stabiilse ja põneva sõidukogemuse pakkumiseks.', 'https://s-mania.com/v1/ee/royalride/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66759, 6, 'GR', 0, 'https://s-mania.com/v1/gr/royalride', 'ΒΑΣΙΛΙΚΗ ΒΟΛΤΑ, ΗΛΕΚΤΡΙΚΗ ΠΕΡΙΠΕΤΕΙΑ!', 'Μια ισχυρή ηλεκτρική μοτοσικλέτα 12V διπλής κίνησης για παιδιά, που διατίθεται σε εκδόσεις Πρίγκιπα (μπλε) και Πριγκίπισσας (ροζ), για μια σταθερή και συναρπαστική εμπειρία οδήγησης.', 'https://s-mania.com/v1/gr/royalride/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64710, 6, 'HR', 0, 'https://s-mania.com/v1/hr/royalride', 'KRALJEVSKA VOŽNJA, ELEKTRIČNA AVANTURA!', 'Snažan 12V električni motocikl s dva pogona za djecu, dostupan u izdanjima Princ (plavo) i Princeza (rozo), za stabilno i uzbudljivo iskustvo vožnje.', 'https://s-mania.com/v1/hr/royalride/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64711, 6, 'HU', 0, 'https://s-mania.com/v1/hu/royalride', 'KIRÁLYI UTAZÁS, ELEKTROMOS KALAND!', 'Egy erős 12V-os, dupla meghajtású elektromos motorkerékpár gyerekeknek, amely herceg (kék) és hercegnő (rózsaszín) kiadásokban is elérhető a stabil és izgalmas motorozási élményért.', 'https://s-mania.com/v1/hu/royalride/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66761, 6, 'IT', 0, 'https://s-mania.it/v1/royalride', 'GIRO REGALE, AVVENTURA ELETTRICA!', 'Una potente moto elettrica a doppia motorizzazione 12V per bambini, disponibile nelle edizioni Principe (blu) e Principessa (rosa), per un\'esperienza di guida stabile ed emozionante.', 'https://s-mania.it/v1/royalride/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66765, 6, 'LT', 0, 'https://s-mania.com/v1/lt/royalride', 'KARALIŠKAS PASIVAŽINĖJIMAS, ELEKTRINIS NUOTYKIS!', 'Galingas 12V dvigubos pavaros elektrinis motociklas vaikams, siūlomas Princo (mėlyna) ir Princesės (rožinė) versijomis, užtikrinantis stabilų ir jaudinantį važiavimą.', 'https://s-mania.com/v1/lt/royalride/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66764, 6, 'LV', 0, 'https://s-mania.com/v1/lv/royalride', 'KARALISKAIS BRAUCIENS, ELEKTRISKAIS PIEDZĪVOJUMS!', 'Jaudīgs 12V divu piedziņas elektriskais motocikls bērniem, pieejams Prinča (zilā) un Princeses (rozā) versijās stabilai un aizraujošai braukšanas pieredzei.', 'https://s-mania.com/v1/lv/royalride/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66760, 6, 'PL', 0, 'https://s-mania.com/v1/pl/royalride', 'KRÓLEWSKA PRZEJAŻDŻKA, ELEKTRYCZNA PRZYGODA!', 'Mocny, dwunapędowy elektryczny motocykl 12V dla dzieci, dostępny w wersjach Książę (niebieski) i Księżniczka (różowy), zapewniający stabilną i ekscytującą jazdę.', 'https://s-mania.com/v1/pl/royalride/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64712, 6, 'RO', 0, 'https://s-mania.com/v1/ro/royalride', 'PLIMBARE REGALĂ, AVENTURĂ ELECTRICĂ!', 'O motocicletă electrică puternică de 12V, cu tracțiune dublă, pentru copii, disponibilă în edițiile Prinț (albastru) și Prințesă (roz), pentru o experiență de condus stabilă și palpitantă.', 'https://s-mania.com/v1/ro/royalride/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64958, 6, 'RS', 0, 'https://s-mania.com/v1/rs/royalride', 'KRALJEVSKA VOŽNJA, ELEKTRIČNA AVANTURA!', 'Snažan 12V električni motor za decu sa dvostrukim pogonom, dostupan u izdanjima Princ (plavo) i Princeza (roze), za stabilno i uzbudljivo iskustvo vožnje.', 'https://s-mania.com/v1/rs/royalride/product-img/var-1.webp', 'READY FOR ADVERTISEMENT', '2026-09-13 12:00:00'),
  (66756, 6, 'SI', 0, 'https://smania.si/v1/royalride', 'KRALJEVSKA VOŽNJA, ELEKTRIČNA AVANTURA!', 'Močan 12V električni motor z dvojnim pogonom za otroke, na voljo v izdajah Princ (modra) in Princesa (roza), za stabilno in vznemirljivo izkušnjo vožnje.', 'https://smania.si/v1/royalride/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66758, 6, 'SK', 0, 'https://s-mania.com/v1/sk/royalride', 'KRÁĽOVSKÁ JAZDA, ELEKTRICKÉ DOBRODRUŽSTVO!', 'Výkonná 12V elektrická motorka s dvojitým pohonom pre deti, dostupná vo verziách Princ (modrá) a Princezná (ružová), pre stabilný a vzrušujúci zážitok z jazdy.', 'https://s-mania.com/v1/sk/royalride/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (63993, 7, 'EN', 1, 'https://s-mania.com/v1/en/spaetzlepro', 'Perfect homemade pasta made easy!', 'A high-quality stainless steel spätzle slicer with a heat-resistant handle and universal fit, designed for fast, professional-grade pasta making and easy cleaning.', 'https://s-mania.com/v1/en/spaetzlepro/product-img/var-1.webp', 'READY FOR ADVERTISEMENT', '2026-09-13 12:00:00'),
  (66204, 7, 'BG', 0, 'https://s-mania.com/v1/bg/spaetzlepro', 'Перфектна домашна паста, направена лесно!', 'Висококачествена резачка за шпецле от неръждаема стомана с термоустойчива дръжка и универсално прилягане, проектирана за бързо, професионално приготвяне на шпецле и лесно почистване.', 'https://s-mania.com/v1/bg/spaetzlepro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66199, 7, 'CZ', 0, 'https://s-mania.com/v1/cz/spaetzlepro', 'Dokonalé domácí těstoviny snadno!', 'Vysoce kvalitní nerezový kráječ na špecle s žáruvzdornou rukojetí a univerzálním uchycením, navržený pro rychlou, profesionální výrobu těstovin a snadné čištění.', 'https://s-mania.com/v1/cz/spaetzlepro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66205, 7, 'DE', 0, 'https://s-mania.de/v1/k/spaetzlepro', 'Perfekte selbstgemachte Nudeln leicht gemacht!', 'Ein hochwertiger Spätzlehobel aus Edelstahl mit hitzebeständigem Griff und universeller Passform, konzipiert für die schnelle, professionelle Spätzlezubereitung und einfache Reinigung.', 'https://s-mania.de/v1/k/spaetzlepro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66208, 7, 'EE', 0, 'https://s-mania.com/v1/ee/spaetzlepro', 'Täiuslik omatehtud pasta, lihtsalt!', 'Kvaliteetne roostevabast terasest spätzli-lõikur kuumakindla käepideme ja universaalse sobivusega, loodud kiireks, professionaalseks spätzli valmistamiseks ja lihtsaks puhastamiseks.', 'https://s-mania.com/v1/ee/spaetzlepro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66201, 7, 'GR', 0, 'https://s-mania.com/v1/gr/spaetzlepro', 'Τέλεια σπιτικά ζυμαρικά, πανεύκολα!', 'Ένας υψηλής ποιότητας κόφτης σπάτζλε από ανοξείδωτο ατσάλι, με ανθεκτική στη θερμότητα λαβή και καθολική εφαρμογή, σχεδιασμένος για γρήγορη παρασκευή ζυμαρικών επαγγελματικού επιπέδου και εύκολο καθαρισμό.', 'https://s-mania.com/v1/gr/spaetzlepro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (63994, 7, 'HR', 0, 'https://s-mania.com/v1/hr/spaetzlepro', 'Savršena domaća tjestenina na jednostavan način!', 'Visokokvalitetni rezač za špecle od nehrđajućeg čelika s ručkom otpornom na toplinu i univerzalnim pristajanjem, dizajniran za brzu izradu tjestenine profesionalne kvalitete i jednostavno čišćenje.', 'https://s-mania.com/v1/hr/spaetzlepro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (63995, 7, 'HU', 0, 'https://s-mania.com/v1/hu/spaetzlepro', 'Tökéletes házi tészta egyszerűen!', 'Kiváló minőségű rozsdamentes acél nokedliszaggató hőálló fogantyúval és univerzális illeszkedéssel, amelyet gyors, professzionális szintű tésztakészítéshez és könnyű tisztítáhbar terveztek.', 'https://s-mania.com/v1/hu/spaetzlepro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66203, 7, 'IT', 0, 'https://s-mania.it/v1/spaetzlepro', 'Pasta fatta in casa perfetta resa facile!', 'Un affettatore per spätzle in acciaio inossidabile di alta qualità con manico resistente al calore e adattabilità universale, progettato per una preparazione di spätzle veloce e di livello professionale e una facile pulizia.', 'https://s-mania.it/v1/spaetzlepro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66207, 7, 'LT', 0, 'https://s-mania.com/v1/lt/spaetzlepro', 'Tobuli naminiai makaronai – lengva pagaminti!', 'Aukštos kokybės nerūdijančio plieno špeclio pjaustyklė su karščiui atsparia rankena ir universaliu pritaikymu, skirta greitai, profesionaliai makaronų gamybai ir lengvam valymui.', 'https://s-mania.com/v1/lt/spaetzlepro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66206, 7, 'LV', 0, 'https://s-mania.com/v1/lv/spaetzlepro', 'Lieliska mājās gatavota pasta, viegli pagatavojama!', 'Augstas kvalitātes nerūsējošā tērauda špecle rīve ar karstumizturīgu rokturi un universālu piemērotību, paredzēta ātrai, profesionāla līmeņa makaronu pagatavošanai un vieglai tīrīšanai.', 'https://s-mania.com/v1/lv/spaetzlepro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66202, 7, 'PL', 0, 'https://s-mania.com/v1/pl/spaetzlepro', 'Idealny domowy makaron na wyciągnięcie ręki!', 'Wysokiej jakości krajalnica do spätzli ze stali nierdzewnej, z żaroodpornym uchwytem i uniwersalnym dopasowaniem, zaprojektowana do szybkiego, profesjonalnego przygotowywania makaronu oraz łatwego czyszczenia.', 'https://s-mania.com/v1/pl/spaetzlepro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (63996, 7, 'RO', 0, 'https://s-mania.com/v1/ro/spaetzlepro', 'Paste de casă perfecte, simplu și ușor!', 'Răzătoare de spätzle din oțel inoxidabil de înaltă calitate, cu mâner rezistent la căldură și potrivire universală, concepută pentru prepararea rapidă a pastelor la standarde profesionale și o curățare ușoară.', 'https://s-mania.com/v1/ro/spaetzlepro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64269, 7, 'RS', 0, 'https://s-mania.com/v1/rs/spaetzlepro', 'Savršena domaća testenina na jednostavan način!', 'Visokokvalitetni rezač za špecle od nerđajućeg čelika sa ručkom otpornom na toplotu i univerzalnim pristajanjem, dizajniran za brzu izradu testenine profesionalnog kvaliteta i jednostavno čišćenje.', 'https://s-mania.com/v1/rs/spaetzlepro/product-img/var-1.webp', 'READY FOR ADVERTISEMENT', '2026-09-13 12:00:00'),
  (66198, 7, 'SI', 0, 'https://smania.si/v1/spaetzlepro', 'Popolne domače testenine, preprosto in hitro!', 'Visokokakovosten rezalnik za špecle iz nerjavečega jekla z ročajem, odpornim na vročino, in univerzalnim prileganjem, zasnovan za hitro, profesionalno pripravo testenin in enostavno čiščenje.', 'https://smania.si/v1/spaetzlepro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (66200, 7, 'SK', 0, 'https://s-mania.com/v1/sk/spaetzlepro', 'Dokonalé domáce cestoviny jednoducho!', 'Vysokokvalitný nerezový krájač na špecle so žiaruvzdornou rukoväťou a univerzálnou kompatibilitou, navrhnutý pre rýchlu, profesionálnu prípravu cestovín a jednoduché čistenie.', 'https://s-mania.com/v1/sk/spaetzlepro/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64543, 8, 'EN', 1, 'https://s-mania.com/v1/en/spikeback', 'Perfect your passes!', 'Transform your football or volleyball skills at home with the revolutionary SpikeBack™ rebounder net! Experience unparalleled control, precision, and agility as this dynamic rebounder returns the ball with perfect accuracy every time.', 'https://s-mania.com/v1/en/spikeback/product-img/var-1.webp', 'READY FOR ADVERTISEMENT', '2026-09-13 12:00:00'),
  (67209, 8, 'BG', 0, 'https://s-mania.com/v1/bg/spikeback', 'Усъвършенствай подаванията си!', 'Подобрете уменията си по футбол или волейбол у дома с революционната мрежа за отскок SpikeBack™! Изпитайте несравним контрол, прецизност и пъргавина, тъй като този динамичен отражател връща топката с перфектна точност всеки път.', 'https://s-mania.com/v1/bg/spikeback/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (67204, 8, 'CZ', 0, 'https://s-mania.com/v1/cz/spikeback', 'Zdokonalte své přihrávky!', 'Zlepšete své fotbalové nebo volejbalové dovednosti doma s revoluční odrazovou sítí SpikeBack™! Zažijte bezkonkurenční kontrolu, přesnost a hbitost, protože tato dynamická odrazová síť vám pokaždé vrátí míč s dokonalou přesností.', 'https://s-mania.com/v1/cz/spikeback/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (67210, 8, 'DE', 0, 'https://s-mania.de/v1/k/spikeback', 'Perfektioniere deine Pässe!', 'Verwandeln Sie Ihre Fähigkeiten im Fußball oder Volleyball zu Hause mit dem revolutionären SpikeBack™ Rebounder-Netz! Erleben Sie unübertroffene Kontrolle, Präzision und Agilität, da dieser dynamische Rebounder den Ball jedes Mal mit perfekter Genauigkeit zurückgibt.', 'https://s-mania.de/v1/k/spikeback/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (67213, 8, 'EE', 0, 'https://s-mania.com/v1/ee/spikeback', 'Täiusta oma sööte!', 'Arenda oma jalgpalli- või võrkpallioskusi kodus revolutsioonilise SpikeBack™ tagasilöögivõrguga! Koge enneolematut kontrolli, täpsust ja väledust, kuna see dünaamiline tagasilöögivõrk tagastab palli iga kord täiusliku täpsusega.', 'https://s-mania.com/v1/ee/spikeback/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (67206, 8, 'GR', 0, 'https://s-mania.com/v1/gr/spikeback', 'Τελειοποίησε τις πάσες σου!', 'Αναβαθμίστε τις δεξιότητές σας στο ποδόσφαιρο ή στο βόλεϊ, στο σπίτι, με το επαναστατικό δίχτυ αναπήδησης SpikeBack™! Απολαύστε απαράμιλλο έλεγχο, ακρίβεια και ευκινησία, καθώς αυτός ο δυναμικός αναπηδητήρας επιστρέφει την μπάλα με τέλεια ακρίβεια κάθε φορά.', 'https://s-mania.com/v1/gr/spikeback/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64544, 8, 'HR', 0, 'https://s-mania.com/v1/hr/spikeback', 'Usavrši svoja dodavanja!', 'Unaprijedite svoje nogometne ili odbojkaške vještine kod kuće uz revolucionarnu mrežu za odbijanje SpikeBack™! Doživite neusporedivu kontrolu, preciznost i agilnost dok ova dinamična mreža za odbijanje vraća loptu sa savršenom preciznošću svaki put.', 'https://s-mania.com/v1/hr/spikeback/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64545, 8, 'HU', 0, 'https://s-mania.com/v1/hu/spikeback', 'Tökéletesítsd a passzaidat!', 'Fejleszd foci- vagy röplabda-készségeidet otthon a forradalmi SpikeBack™ visszapattanó hálóval! Tapasztald meg a páratlan labdakontrollt, pontosságot és agilitást, ahogy ez a dinamikus visszapattanó minden alkalommal tökéletes pontossággal adja vissza a labdát.', 'https://s-mania.com/v1/hu/spikeback/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (67208, 8, 'IT', 0, 'https://s-mania.it/v1/spikeback', 'Perfeziona i tuoi passaggi!', 'Trasforma le tue abilità calcistiche o pallavolistiche a casa con la rivoluzionaria rete da rimbalzo SpikeBack™! Sperimenta un controllo, una precisione e un\'agilità senza pari, con questa rete da rimbalzo dinamica che ti restituisce la palla con perfetta precisione ogni volta.', 'https://s-mania.it/v1/spikeback/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (67212, 8, 'LT', 0, 'https://s-mania.com/v1/lt/spikeback', 'Tobulinkite savo perdavimus!', 'Patobulinkite savo futbolo ar tinklinio įgūdžius namuose su revoliuciniu SpikeBack™ atmušimo tinklu! Patirkite neprilygstamą kontrolę, tikslumą ir vikrumą, nes šis dinamiškas atmušėjas kaskart grąžina kamuolį su nepriekaištingu tikslumu.', 'https://s-mania.com/v1/lt/spikeback/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (67211, 8, 'LV', 0, 'https://s-mania.com/v1/lv/spikeback', 'Pilnveido savas piespēles!', 'Uzlabojiet savas futbola vai volejbola prasmes mājās ar revolucionāro SpikeBack™ atsitiena tīklu! Izbaudiet nepārspējamu kontroli, precizitāti un veiklību, jo šis dinamiskais atsitiena tīkls katru reizi atgriež bumbu ar perfektu precizitāti.', 'https://s-mania.com/v1/lv/spikeback/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (67207, 8, 'PL', 0, 'https://s-mania.com/v1/pl/spikeback', 'Doskonal swoje podania!', 'Rozwiń swoje umiejętności piłkarskie lub siatkarskie w domu dzięki rewolucyjnej siatce odbijającej SpikeBack™! Doświadcz niezrównanej kontroli, precyzji i zwinności, gdyż ten dynamiczny odbijacz zwraca piłkę z perfekcyjną celnością za każdym razem.', 'https://s-mania.com/v1/pl/spikeback/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64546, 8, 'RO', 0, 'https://s-mania.com/v1/ro/spikeback', 'Îmbunătățește-ți pasele!', 'Transformă-ți abilitățile de fotbal sau volei acasă cu plasa revoluționară de rebounder SpikeBack™! Experimentează control, precizie și agilitate fără egal, pe măsură ce acest rebounder dinamic îți returnează mingea cu o precizie perfectă de fiecare dată.', 'https://s-mania.com/v1/ro/spikeback/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (64959, 8, 'RS', 0, 'https://s-mania.com/v1/rs/spikeback', 'Usavršite dodavanja!', 'Unapredite svoje fudbalske ili odbojkaške veštine kod kuće uz revolucionarnu mrežu za odbijanje lopte SpikeBack™! Doživite neuporedivu kontrolu, preciznost i agilnost, dok ova dinamična mreža za odbijanje vraća loptu sa savršenom preciznošću svaki put.', 'https://s-mania.com/v1/rs/spikeback/product-img/var-1.webp', 'READY FOR ADVERTISEMENT', '2026-09-13 12:00:00'),
  (67203, 8, 'SI', 0, 'https://smania.si/v1/spikeback', 'Izpopolnite svoje podaje!', 'Dvignite svoje nogometne ali odbojkarske spretnosti na višjo raven doma z revolucionarno odbojno mrežo SpikeBack™! Izkusite neprimerljiv nadzor, natančnost in okretnost, saj ta dinamična odbojna mreža žogo vedno vrača s popolno natančnostjo.', 'https://smania.si/v1/spikeback/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
  (67205, 8, 'SK', 0, 'https://s-mania.com/v1/sk/spikeback', 'Zdokonaľte svoje prihrávky!', 'Zlepšite svoje futbalové alebo volejbalové zručnosti doma s revolučnou odrazovou sieťou SpikeBack™! Zažite bezkonkurenčnú kontrolu, presnosť a obratnosť, keďže táto dynamická odrazová sieť vracia loptu s dokonalou presnosťou zakaždým.', 'https://s-mania.com/v1/sk/spikeback/product-img/var-1.webp', 'ADVERTISING', '2026-09-13 12:00:00'),
